    private LoginRequest loginModel = new();
    private string? successMessage;
    private string? errorMessage;

    private bool isLoading = false;
    private bool rememberMe = false;

    [Inject] private AppState AppState { get; set; }
    [Inject] private TokenServices TokenServices { get; set; }
    [Inject] private NavigationManager NavigationManager { get; set; }
    [Inject] private HttpClient HttpClient { get; set; }
    
    [Inject] private JwtAuthStateProvider AuthStateProviders { get; set; }
      private const string TokenKey = "authToken";

    protected override async Task OnInitializedAsync()
    {
        var token = await TokenServices.GetToken();
        if (!string.IsNullOrEmpty(token))
        {
            var isValid = await ValidateTokenWithApi(token);
            if (isValid)
            {
                NavigationManager.NavigateTo("/dashboard", true);
                return;
            }
            else
            {
                await TokenServices.RemoveToken();
                await _localStorage.RemoveItemAsync("userInfo");
                await AuthStateProvider.NotifyUserLogout();
            }
        }
    }
     private async Task<bool> ValidateTokenWithApi(string token)
    {
        try
        {
            HttpClient.DefaultRequestHeaders.Authorization = 
                new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", token);

            var response = await HttpClient.GetAsync(ApiEndpoints.Auth.ValidateToken);
            return response.IsSuccessStatusCode;
        }
        catch
        {
            return false;
        }
    }

    private async Task HandleLogin()
    {
        isLoading = true;
        errorMessage = null;
        successMessage = null;

        try
        {
            AuthResponse? response = await AuthService.LoginAsync(loginModel);
            switch (response.StatusCode)
            {
                case 401:
                    errorMessage = response.Message;
                    break;

                case 423:
                    errorMessage = response.Message;
                    break;

                case 400:
                    errorMessage = response.Message;
                    break;

                case 500:
                    errorMessage = "An unexpected server error occurred.";
                    break;

                default:
                    // Save token
                    await TokenServices.SaveToken(response.Data!.accessToken);
                    await TokenServices.SaveTokenAndUserInfo(response);
                    // Notify authentication
                    await AuthStateProvider.NotifyUserAuthentication(response.Data.accessToken);
            
                    successMessage = "Login successful!";
                    StateHasChanged();
                    
                    // Wait for message to show
                    await Task.Delay(800);
                    
                    // Force navigate to dashboard
                    Navigation.NavigateTo("/dashboard", true); 
                    break;
            }
        }
        catch (Exception ex)
        {
            errorMessage = "Server error. Try again later.";
            Console.WriteLine($"Login error: {ex.Message}");
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ShowSuccess(string message)
    {
        successMessage = message;
        errorMessage = null;
    }

    private void ShowError(string message)
    {
        errorMessage = message;
        successMessage = null;
    }
    private async Task AutoClear()
    {
        await Task.Delay(3000);
        errorMessage = null;
        successMessage = null;
        StateHasChanged();
    }

